// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract ReentrantCollector {
    DEP_BANK public c;
    uint256 public amount;
    bool private __entered;

    constructor(DEP_BANK _c, uint256 _amount) {
        c = _c;
        amount = _amount;
    }

    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.Collect(amount);
        }
    }

    function attack() external payable {
        c.Deposit{value: msg.value}();
        c.Collect(amount);
    }
}

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 initialDeposit, uint256 collectAmount) public {
        vm.assume(initialDeposit <= VALUE_CAP);
        address actor = address(new ReentrantCollector(c, collectAmount));
        vm.deal(actor, initialDeposit);

        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();

        vm.prank(actor);
        (bool depositOk,) = actor.call{value: initialDeposit}(abi.encodeWithSignature("attack()"));
        require(depositOk, "attack failed");

        uint256 balanceAfter = c.balances(actor);
        uint256 received = actor.balance;

        bool correct = balanceAfter == initialDeposit - received || (balanceAfter <= initialDeposit && received == 0);
        assertTrue(correct, "reentrant Collect must not leave a stale balance");
    }
}
